/** Бүх түлхүүрийн тоо (зүүн/баруун хувилбарууд давхардсан). */
export const ORGAN_ENTRIES_MN_COUNT = Object.keys(ORGAN_ENTRIES_MN).length;

/**
 * Атлас дахь нэрээс монгол тайлбар олох туслах функц.
 * Эхлээд бүтэн нэрийн дагуу, дараа нь "left "/"right " угтрыг хасаж
 * хайж, олдсон хувилбарыг буцаана.
 */
export function organEntryMn(name: string): OrganEntryMn | undefined {
  const lower = name.toLowerCase();
  return ORGAN_ENTRIES_MN[lower] ?? ORGAN_ENTRIES_MN[lower.replace(/^(left|right) /, '')];
}

/** Тухайн нэртэй тайлбар олдох эсэхийг шалгана. */
export function hasOrganEntryMn(name: string): boolean {
  return Boolean(organEntryMn(name));
}
